def first_sorted_index(values, target):
    lo = 0
    hi = len(values)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(values) and values[lo] == target:
        return lo
    return -1

print(first_sorted_index([1, 3, 3, 7, 9], 3))
print(first_sorted_index([1, 3, 3, 7, 9], 4))
print(first_sorted_index([], 3))

def first_sorted_index(values, target):
    lo, hi = 0, len(values)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(values) and values[lo] == target:
        return lo
    return -1

for values in [[], [2, 2, 2], [1, 4, 7]]:
    print(first_sorted_index(values, 2))
